import math
def priority(task, state, c=1.0, c2=2.0, m=4.0, w=0.3):
    est = max(task.estimated_runtime, 1e-6)
    wait = state.now - task.release
    ratio = wait / est
    tier = m if task.tenant == 'premium' else 1.0
    if ratio >= c2:
        return 1e7 + tier * (ratio + 1.0 / est)
    if ratio >= c:
        return 1e6 + tier * (w * ratio + 1.0 / est)
    slack = max(0.0, task.due - est - state.now)
    urgency = math.exp(-slack / max(2.0 * state.mean_est, 1e-6))
    return tier * (urgency / est + w * ratio / est) + 0.1 / est

